def find_length(binary_string):
    """
    Finds the maximum difference between the number of 0s and number of 1s in any sub-string of the given binary string.

    :param binary_string: A string consisting of '0's and '1's.
    :return: The maximum difference between the number of 0s and number of 1s in any sub-string.
    """
    max_diff = 0
    current_diff = 0
    diff_map = {0: -1}

    for i, char in enumerate(binary_string):
        if char == '0':
            current_diff += 1
        else:
            current_diff -= 1

        if current_diff in diff_map:
            max_diff = max(max_diff, i - diff_map[current_diff])
        else:
            diff_map[current_diff] = i

    return max_diff
