from functools import lru_cache

@lru_cache(maxsize=None)
def get_total_number_of_sequences(m, n):
    """
    Returns the number of possible sequences of length n, where each element is a positive integer
    and is greater than or equal to twice the previous element but less than or equal to m.

    :param m: int, the maximum value an element in the sequence can take
    :param n: int, the length of the sequence
    :return: int, the number of valid sequences
    """
    def dp(prev, length):
        if length == n:
            return 1
        count = 0
        for i in range(prev * 2, m + 1):
            count += dp(i, length + 1)
        return count

    return dp(1, 1)
